INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist das Dualsystem nur in Deutschland üblich?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Österreich, Schweiz"}, {"text": "Ja", "correct": false, "because": "Nicht exklusiv"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt das Dualsystem?', 3, '[{"text": "Praxis und Theorie verbinden", "correct": true, "because": "Betrieb und Schule"}, {"text": "Nur theoretische Bildung", "correct": false, "because": "Praxis zentral"}, {"text": "Hardware-Entwicklung", "correct": false, "because": "Ausbildungsfokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zum Dualsystem?', 5, '[{"text": "Betriebliche Ausbildung", "correct": true, "because": "Praxis im Unternehmen"}, {"text": "Berufsschulunterricht", "correct": true, "because": "Theoretische Grundlagen"}, {"text": "Universitätsstudium", "correct": false, "because": "Nicht Teil"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das Dualsystem kombiniert Praxis und Theorie. b) Es ist nur für Informatiker.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Viele Berufe"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich beim Dualsystem?', 4, '[{"text": "Praxisphasen", "correct": false, "because": "Kernbestandteil"}, {"text": "Theorieunterricht", "correct": false, "because": "Ergänzung zur Praxis"}, {"text": "Papierfarbe", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das Dualsystem nur für Jugendliche ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Erwachsene"}, {"text": "Ja", "correct": false, "because": "Nicht altersbeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Institutionen sind am Dualsystem beteiligt?', 3, '[{"text": "IHK", "correct": true, "because": "Prüfungen und Standards"}, {"text": "Universitäten", "correct": false, "because": "Studium separat"}, {"text": "Schulen", "correct": false, "because": "Berufsschulen spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet das Dualsystem?', 5, '[{"text": "Praxisnähe", "correct": true, "because": "Direkte Erfahrung"}, {"text": "Theoretisches Wissen", "correct": true, "because": "Schulunterricht"}, {"text": "Kostenlose Universität", "correct": false, "because": "Kein Studium"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Das Dualsystem fördert Berufserfahrung. b) Es ist nur für technische Berufe. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Viele Berufsfelder"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für das Dualsystem?', 4, '[{"text": "Ausbildungsvertrag", "correct": false, "because": "Pflicht"}, {"text": "Berufsschulbesuch", "correct": false, "because": "Teil des Systems"}, {"text": "Doktorgrad", "correct": true, "because": "Nicht erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist das Dualsystem kostenlos für Auszubildende?', 2, '[{"text": "Ja", "correct": true, "because": "Vergütung üblich"}, {"text": "Nein", "correct": false, "because": "Kein Schulgeld"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Phasen umfasst das Dualsystem?', 4, '[{"text": "Betriebliche Praxis", "correct": true, "because": "Arbeit im Unternehmen"}, {"text": "Theoretischer Unterricht", "correct": true, "because": "Berufsschule"}, {"text": "Forschungsprojekte", "correct": false, "because": "Nicht Teil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass das Dualsystem nur für Schulabgänger ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Umschüler"}, {"text": "Ja", "correct": false, "because": "Breitere Zielgruppe"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich im Dualsystem?', 3, '[{"text": "Praxisbezug", "correct": true, "because": "Berufserfahrung"}, {"text": "Schnellabschluss", "correct": false, "because": "Qualität zählt"}, {"text": "Papierformate", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das Dualsystem kombiniert Betrieb und Schule. b) Es dauert immer 5 Jahre.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Dauer variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Berufe nutzen das Dualsystem?', 5, '[{"text": "Fachinformatiker", "correct": true, "because": "IT-Ausbildung"}, {"text": "Mechatroniker", "correct": true, "because": "Technischer Beruf"}, {"text": "Professor", "correct": false, "because": "Akademisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist im Dualsystem unwichtig?', 3, '[{"text": "Berufsschulbesuch", "correct": false, "because": "Theorie nötig"}, {"text": "Praktische Erfahrung", "correct": false, "because": "Praxis zentral"}, {"text": "Schriftart", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist das Dualsystem gesetzlich geregelt?', 3, '[{"text": "Ja", "correct": true, "because": "Berufsbildungsgesetz"}, {"text": "Nein", "correct": false, "because": "Reguliert"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das Dualsystem eine Vergütung beinhaltet?', 2, '[{"text": "Ja", "correct": true, "because": "Auszubildende bezahlt"}, {"text": "Nein", "correct": false, "because": "Vergütung üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für das Dualsystem zentral?', 4, '[{"text": "Kombination Praxis/Theorie", "correct": true, "because": "Grundprinzip"}, {"text": "Nur Praxis", "correct": false, "because": "Theorie nötig"}, {"text": "Universitätsabschluss", "correct": false, "because": "Nicht Ziel"}]');
